#include <csignal>
#include <cassert>
#include <type_traits>
#include <utility>
volatile std::sig_atomic_t signal_count = 0;
void handler(int) { signal_count = 1; }
int main() {
    std::sig_atomic_t before = signal_count;
    (void)before;
    auto previous = std::signal(SIGINT, handler);
    assert(previous != SIG_ERR);
    std::raise(SIGINT);
    assert(signal_count == 1);
    std::signal(SIGINT, SIG_IGN);
    std::raise(SIGINT);
    assert(signal_count == 1);
    std::signal(SIGINT, previous);
    int signals[]{SIGABRT, SIGFPE, SIGILL, SIGINT, SIGSEGV, SIGTERM};
    assert(signals[3] == SIGINT);
}
